"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["56989"],{91199(e){e.exports=JSON.parse('{"id":"F222","slug":"justified-price-to-book","name":"Justified Price-to-Book Ratio (Banks)","subject":"Valuation","section":"Valuation","topic":"Valuing banks and insurers","level":"Intermediate","aliases":["P/B","price to book","bank valuation","justified P/B"],"formula":{"latex":"\\\\frac{P}{B}=\\\\frac{ROE-g}{r-g}","also":[],"text":"Justified P/B = (ROE - g) / (r - g)"},"symbols":[{"symbol":"P/B","meaning":"Price-to-book ratio the fundamentals justify","unit":"number"},{"symbol":"ROE","meaning":"Return on equity","unit":"per year"},{"symbol":"g","meaning":"Sustainable growth rate","unit":"per year"},{"symbol":"r","meaning":"Required return on equity","unit":"per year"}],"when_to_use":"Use it to value banks and other financial firms, whose book value is close to market value. A bank earning more than its cost of equity should trade above book value.","worked_example":{"problem":"A bank has a return on equity of 14%, expected growth of 4% and a required return of 10%. What price-to-book ratio is justified, and what is the value if book value per share is 30?","inputs":{"roe":14,"g":4,"r":10,"bv":30},"steps":[{"label":"P/B = (ROE - g) / (r - g)","working":"(0.14-0.04) / (0.1-0.04)","value":"1.67"},{"label":"Value per share = P/B x book value per share","working":"1.66667 x 30","value":"50.00"}],"answer":"The justified P/B is 1.67, so the share is worth 50.00. The bank earns more than its cost of equity, so it is worth more than book value."},"calculator":{"available":true,"inputs":[{"id":"roe","label":"Return on equity","unit":"%","type":"number","default":14,"hint":""},{"id":"g","label":"Growth rate","unit":"%","type":"number","default":4,"hint":""},{"id":"r","label":"Required return","unit":"%","type":"number","default":10,"hint":""},{"id":"bv","label":"Book value per share","unit":"money","type":"number","default":30,"hint":""}],"checks":[{"expr":"r>g","message":"The required return must be higher than the growth rate."}],"steps":[{"id":"pb","label":"P/B = (ROE - g) / (r - g)","expr":"(roe-g)/(r-g)","format":"num2"},{"id":"value","label":"Value per share = P/B x book value per share","expr":"pb*bv","format":"money"}],"results":["pb","value"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"pb":1.6666666666666667,"value":50}},"finder":{"finds":"Price-to-book a bank deserves","needs":"ROE, growth, required return, book value"},"related":[{"slug":"sustainable-growth-rate","name":"Sustainable Growth Rate"},{"slug":"residual-income","name":"Residual Income Valuation"},{"slug":"gordon-growth-model","name":"Dividend Discount Model (Gordon Growth)"}],"related_ids":["F176","F228","F205"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mfrac><mi>P</mi><mi>B</mi></mfrac><mo>=</mo><mfrac><mrow><mi>R</mi><mi>O</mi><mi>E</mi><mo>\u2212</mo><mi>g</mi></mrow><mrow><mi>r</mi><mo>\u2212</mo><mi>g</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\frac{P}{B}=\\\\frac{ROE-g}{r-g}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"jensens-alpha","name":"Jensen\'s Alpha"},"next":{"slug":"kelly-criterion","name":"Kelly Criterion"},"lesson":null,"total":522}')}}]);